log.raw:
{
  "bullets": [
    "46 fire-rated plasterboards delivered to Neubau Schulzentrum Nord, Munich, with 4 units short-delivered and back-ordered for 21 October.",
    "3 boards arrived with water damage on pallet 2, documented by photographs and signed by the site foreman.",
    "Delivery completed between 07:40 and 09:15 by driver M. Keller using a crane lorry."
  ],
  "risk": "medium",
  "risk_reason": "Shortage of 4 boards and water damage to 3 units may cause schedule delays or rework."
}

{
  "bullets": [
    "Stack of jointing compound buckets tipped over near lift shaft, causing a temporary slip hazard in the stairwell.",
    "No injuries occurred, but the area required cleaning until 11:20 and the pallet was relocated to the ground floor.",
    "Open actions include developing a storage plan for all levels and conducting a toolbox talk on stacking limits by 9 November."
  ],
  "risk": "medium",
  "risk_reason": "Incident created a slip hazard and revealed systemic failures in storage planning and area barriers."
}

{
  "bullets": [
    "15 mm Type F plasterboard achieves 90 min fire resistance in system FR-90 with 75 mm steel studs at 400 mm centres and double layers.",
    "Maximum stud spacing is 600 mm for single layers, and the product is unsuitable for permanently wet areas without moisture-resistant board.",
    "Fixing requires screws every 250 mm at edges and 300 mm in the field, with storage limited to 8 pallets high on level, dry surfaces."
  ],
  "risk": "low",
  "risk_reason": "Standard product data with clear installation and storage constraints."
}

